package by.bsuir.analytics;
import by.bsuir.repair.contract.*; import by.bsuir.repair.runtime.*; import io.grpc.stub.StreamObserver; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.sql.Date; import java.time.*; import java.util.*;
@Service public class AnalyticsGrpcService extends AnalyticsServiceGrpc.AnalyticsServiceImplBase {
 private final JdbcTemplate jdbc; private final Jsons jsons; public AnalyticsGrpcService(JdbcTemplate jdbc,Jsons jsons){this.jdbc=jdbc;this.jsons=jsons;}
 @KafkaListener(topics={EventTopics.REQUEST,EventTopics.WORK_ORDER,EventTopics.PAYMENT}) @Transactional public void consume(String raw){var env=jsons.read(raw);UUID event=UUID.fromString(env.get("eventId").toString());if(jdbc.queryForObject("select count(*) from processed_events where event_id=?",Integer.class,event)>0)return;String type=env.get("eventType").toString();var payload=jsons.read(env.get("payload").toString());LocalDate day=Instant.parse(env.get("occurredAt").toString()).atZone(ZoneOffset.UTC).toLocalDate();ensureDay(day);if(type.equals("RepairRequestCreated"))jdbc.update("update daily_repair_metrics set requests_count=requests_count+1 where metric_date=?",Date.valueOf(day));if(type.equals("WorkOrderCompleted")){jdbc.update("update daily_repair_metrics set completed_count=completed_count+1 where metric_date=?",Date.valueOf(day));if(payload.get("employeeId")!=null){UUID employee=UUID.fromString(payload.get("employeeId").toString());int rows=jdbc.update("update employee_workload_metrics set completed_count=completed_count+1 where metric_date=? and employee_id=?",Date.valueOf(day),employee);if(rows==0)jdbc.update("insert into employee_workload_metrics(metric_date,employee_id,assigned_count,completed_count) values(?,?,0,1)",Date.valueOf(day),employee);}}if(type.equals("PaymentCompleted"))jdbc.update("update daily_repair_metrics set revenue=revenue+? where metric_date=?",new BigDecimal(payload.get("amount").toString()),Date.valueOf(day));if(type.equals("WorkOrderCreated")&&payload.get("employeeId")!=null){UUID employee=UUID.fromString(payload.get("employeeId").toString());int count=jdbc.queryForObject("select count(*) from employee_workload_metrics where metric_date=? and employee_id=?",Integer.class,Date.valueOf(day),employee);if(count==0)jdbc.update("insert into employee_workload_metrics(metric_date,employee_id,assigned_count,completed_count) values(?,?,1,0)",Date.valueOf(day),employee);else jdbc.update("update employee_workload_metrics set assigned_count=assigned_count+1 where metric_date=? and employee_id=?",Date.valueOf(day),employee);}if(type.equals("WorkOrderServiceAdded")){UUID service=UUID.fromString(payload.get("serviceId").toString());int count=jdbc.queryForObject("select count(*) from service_demand_metrics where period_start=? and service_id=?",Integer.class,Date.valueOf(day.withDayOfMonth(1)),service);if(count==0)jdbc.update("insert into service_demand_metrics(period_start,service_id,service_name,usage_count,revenue) values(?,?,?,?,?)",Date.valueOf(day.withDayOfMonth(1)),service,payload.get("serviceName"),Integer.parseInt(payload.get("quantity").toString()),new BigDecimal(payload.get("revenue").toString()));else jdbc.update("update service_demand_metrics set usage_count=usage_count+?,revenue=revenue+? where period_start=? and service_id=?",Integer.parseInt(payload.get("quantity").toString()),new BigDecimal(payload.get("revenue").toString()),Date.valueOf(day.withDayOfMonth(1)),service);}jdbc.update("insert into processed_events(event_id,processed_at) values(?,?)",event,java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));}
 private void ensureDay(LocalDate day){if(jdbc.queryForObject("select count(*) from daily_repair_metrics where metric_date=?",Integer.class,Date.valueOf(day))==0)jdbc.update("insert into daily_repair_metrics(metric_date,requests_count,completed_count,revenue,total_duration_hours) values(?,0,0,0,0)",Date.valueOf(day));}
 @Override public void getAnalytics(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);LocalDate from=LocalDate.parse(jsons.string(in,"from").substring(0,10)),to=LocalDate.parse(jsons.string(in,"to").substring(0,10));var totals=jdbc.queryForMap("select coalesce(sum(requests_count),0) AS \"repairsCount\",coalesce(sum(completed_count),0) AS \"completedCount\",coalesce(sum(revenue),0) revenue,coalesce(sum(total_duration_hours),0) duration from daily_repair_metrics where metric_date between ? and ?",Date.valueOf(from),Date.valueOf(to));int completed=Integer.parseInt(totals.get("completedCount").toString());BigDecimal duration=new BigDecimal(totals.get("duration").toString());totals.put("avgDurationHours",completed==0?BigDecimal.ZERO:duration.divide(BigDecimal.valueOf(completed),2,RoundingMode.HALF_UP));var popular=jdbc.queryForList("select service_name name,sum(usage_count) AS \"usageCount\",sum(revenue) revenue from service_demand_metrics where period_start between ? and ? group by service_name order by sum(usage_count) desc",Date.valueOf(from.withDayOfMonth(1)),Date.valueOf(to));totals.put("popularServices",popular);totals.put("mostRequestedService",popular.isEmpty()?"Нет данных":popular.get(0).get("name"));totals.put("employeeWorkload",jdbc.queryForList("select employee_id AS \"employeeId\",sum(assigned_count) AS \"assignedCount\",sum(completed_count) AS \"completedCount\" from employee_workload_metrics where metric_date between ? and ? group by employee_id",Date.valueOf(from),Date.valueOf(to)));jsons.reply(obs,totals);}catch(Throwable e){jsons.fail(obs,e);}}
}



